def solve(payload):
    import json
    try:
        data = json.loads(payload)
    except json.JSONDecodeError:
        return "error"
    name = data.get("name")
    age = data.get("age")
    if type(name) is not str or not name.strip():
        return "error"
    if type(age) is not int or age < 0:
        return "error"
    return {"name": name, "age": age}
